messages.content:
Tool response:
Tool: bulk_close_maintenance_tickets
Description: Bulk Close Maintenance Tickets
Parameters:
    {
      "type": "object",
      "properties": {
        "tickets": {
          "items": {
            "properties": {
              "ticket_number": {
                "type": "string",
                "title": "Ticket Number",
                "description": "Maintenance ticket number to close"
              },
              "equipment_asset_tag": {
                "type": "string",
                "title": "Equipment Asset Tag",
                "description": "Equipment asset tag associated with the ticket"
              },
              "calibration_event_id": {
                "type": "string",
                "title": "Calibration Event Id",
                "description": "Completed calibration event ID to link"
              }
            },
            "type": "object",
            "required": [
              "ticket_number",
              "equipment_asset_tag",
              "calibration_event_id"
            ],
            "title": "TicketItem"
          },
          "type": "array",
          "title": "Tickets",
          "description": "List of ticket details to process"
        },
        "completion_reason": {
          "type": "string",
          "title": "Completion Reason",
          "description": "Reason for completing the tickets late"
        }
      },
      "required": [
        "tickets",
        "completion_reason"
      ]
    }
